    private static void infusion(String key,String research,TcStack output,int instability,AspectList aspects,TcIngredient center,TcIngredient... parts){TcRecipes.register(new InfusionRecipe("TX:"+key,research,output,instability,aspects,center,List.of(parts)));}
    public static void arcane(String key,String research,TcStack output,AspectList aspects,String[] pattern,Object... symbols){
        List<TcIngredient> grid=new ArrayList<>();int width=pattern[0].length();
        for(String row:pattern)for(char c:row.toCharArray()){
            TcIngredient ingredient=TcIngredient.EMPTY;
            if(c!=' ')for(int n=0;n<symbols.length;n+=2)if((Character)symbols[n]==c)ingredient=(TcIngredient)symbols[n+1];
            grid.add(ingredient);
        }
        TcRecipes.register(new ShapedArcaneRecipe("TX:"+key,research,output,aspects,width,pattern.length,grid));
    }
